FUNCTION_BLOCK FB_ValueTracker
    VAR_INPUT
        aaa : DINT := 1;
        bbb : DINT := 0;
        CYCLE : DINT := 0;
    END_VAR
    VAR_OUTPUT
        OUT : DINT;
        UPDATED_CYCLE : DINT;
    END_VAR

    VAR
        // Local variable to hold the updated values of aaa and bbb
        updated_aaa : DINT;
        updated_bbb : DINT;
    END_VAR

    // Initialize local variables with input values
    updated_aaa := aaa;
    updated_bbb := bbb;

    // Logic to increment aaa and bbb based on their comparative values
    IF updated_aaa = updated_bbb THEN
        updated_aaa := updated_aaa + 1;
    ELSIF updated_aaa > updated_bbb THEN
        updated_bbb := updated_bbb + 1;
    ELSIF updated_aaa < updated_bbb THEN
        updated_aaa := updated_aaa + 1;
    END_IF;

    // Calculate the output as the difference between updated values
    OUT := updated_aaa - updated_bbb;

    // Increment the cycle counter
    UPDATED_CYCLE := CYCLE + 1;

    // Update the original variables for the next cycle
    aaa := updated_aaa;
    bbb := updated_bbb;

END_FUNCTION_BLOCK
